136	function parseServeArgs(args) {
137	  const positionals = [];
138	  let port = 3000;
139	  let historyFile = null;
140	  for (let index = 0; index < args.length; index += 1) {
141	    const arg = args[index];
142	    if (arg === '--port') {
143	      index += 1;
144	      if (index >= args.length) throw new SnapshotError('INVALID_OPTIONS', '--port requires a value');
145	      port = parsePort(args[index]);
146	    } else if (arg.startsWith('--port=')) {
147	      port = parsePort(arg.slice('--port='.length));
148	    } else if (arg === '--history') {
149	      index += 1;
150	      if (index >= args.length || args[index] === '') throw new SnapshotError('INVALID_OPTIONS', '--history requires a value');
151	      historyFile = args[index];
152	    } else if (arg.startsWith('--history=')) {
153	      historyFile = arg.slice('--history='.length);
154	      if (historyFile === '') throw new SnapshotError('INVALID_OPTIONS', '--history requires a value');
155	    } else if (arg.startsWith('--')) {
156	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
157	    } else {
158	      positionals.push(arg);
159	    }
160	  }
161	  if (positionals.length !== 1) {
162	    throw new SnapshotError('INVALID_OPTIONS', 'usage: serve <snapshot> [--port <port>] [--history <file>]');
163	  }
164	  if (historyFile !== null && path.resolve(positionals[0]) === path.resolve(historyFile)) {
165	    throw new SnapshotError('INVALID_OPTIONS', 'snapshot and history must be different files');
166	  }
167	  return { file: positionals[0], port, historyFile };
168	}
169	
170	function readText(file) {
171	  return fs.readFileSync(file, 'utf8');
172	}
173	
174	function writeStaging(file, content) {
175	  const temp = stagingPath(file);
176	  try {
177	    fs.writeFileSync(temp, content, 'utf8');
178	  } catch (error) {
179	    try {
180	      fs.rmSync(temp, { force: true });
181	    } catch {
182	      // best-effort cleanup
183	    }
184	    throw new SnapshotError('IO_ERROR', `cannot write file ${file}: ${error.message}`);
185	  }
186	  return temp;
187	}
188	
189	function removeQuiet(file) {
190	  try {
191	    fs.rmSync(file, { force: true });
192	  } catch {
193	    // best-effort cleanup
194	  }
195	}
196	
197	// Commits snapshot and history together. The history file is the commit
198	// marker: it is installed first and embeds the new snapshot checksum, so a
199	// kill between the two renames leaves a history the next startup replays to
200	// reconstruct the snapshot. A failed I/O step rolls the files back to the
201	// pre-commit state; the caller only swaps in-memory state after this returns.
202	function commitWithHistory(snapshotFile, historyFile, backupFile, snapshot, historySnapshot) {
203	  const snapshotText = `${JSON.stringify(snapshot)}\n`;
204	  const historyText = `${JSON.stringify(historySnapshot)}\n`;
205	  const snapshotTemp = writeStaging(snapshotFile, snapshotText);
206	  let historyTemp;
207	  try {
208	    historyTemp = writeStaging(historyFile, historyText);
209	  } catch (error) {
210	    removeQuiet(snapshotTemp);
211	    throw error;
212	  }
213	  const hadHistory = fs.existsSync(historyFile);
214	  try {
215	    if (hadHistory) fs.renameSync(historyFile, backupFile);
216	    fs.renameSync(historyTemp, historyFile);
217	  } catch (error) {
218	    if (hadHistory) {
219	      try {
220	        fs.renameSync(backupFile, historyFile);
221	      } catch {
222	        // startup recovery reconciles whatever remains
223	      }
224	    }
225	    removeQuiet(snapshotTemp);
226	    removeQuiet(historyTemp);
227	    throw new SnapshotError('IO_ERROR', `cannot write history file ${historyFile}: ${error.message}`);
228	  }
229	  try {
230	    fs.renameSync(snapshotTemp, snapshotFile);
231	  } catch (error) {
232	    try {
233	      if (hadHistory) {
234	        fs.renameSync(backupFile, historyFile);
235	      } else {
236	        fs.rmSync(historyFile, { force: true });
237	      }
238	    } catch {
239	      // startup recovery reconciles whatever remains
240	    }
241	    removeQuiet(historyTemp);
242	    throw new SnapshotError('IO_ERROR', `cannot write snapshot file ${snapshotFile}: ${error.message}`);
243	  }
244	  removeQuiet(backupFile);
245	}
246	
247	// Loads the snapshot/history pair and brings both to a single consistent
248	// state. Returns { workspace, ledger }. Throws a SnapshotError (IO_ERROR,
249	// INVALID_SNAPSHOT, or INVALID_HISTORY) on any unrecoverable problem; files
250	// are left untouched in that case.
251	function loadState(file, historyFile) {
252	  const workspace = new Workspace();
253	  let snapshot = null;
254	  if (fs.existsSync(file)) {
255	    const text = readSnapshotFile(file);
256	    workspace.importJSON(text, { mode: 'replace' });
257	    snapshot = workspace.exportJSON();
258	  } else {
259	    snapshot = workspace.exportJSON();
260	  }
261	
262	  if (historyFile === null) return { workspace, ledger: null };
263	
264	  const backupFile = `${historyFile}.bak`;
265	  // A kill between moving the old history aside and installing the new one
266	  // leaves only the backup; restore the pre-commit history before proceeding.
267	  if (!fs.existsSync(historyFile) && fs.existsSync(backupFile)) {
268	    try {
269	      fs.renameSync(backupFile, historyFile);
270	    } catch (error) {
271	      throw new SnapshotError('IO_ERROR', `cannot recover history file ${historyFile}: ${error.message}`);
272	    }
273	  }
274	
275	  if (!fs.existsSync(historyFile)) {
276	    // First run with a history file: revision 1 baselines the current content.
277	    // The file itself appears with the first successful write.
278	    return { workspace, ledger: HistoryStore.baseline(workspace.list()) };
279	  }
280	
281	  const ledger = loadHistoryFile(historyFile, readText);
282	  removeQuiet(backupFile);
283	  if (ledger.snapshotChecksum === snapshot.checksum) {
284	    return { workspace, ledger };
285	  }
286	
287	  // The files disagree: the history ledger is authoritative (it records every
288	  // acknowledged commit). Reconstruct the snapshot from its replay and install
289	  // it atomically.
290	  const recovered = snapshotFromDocuments(ledger.replayedDocuments().values());
291	  if (recovered.checksum !== ledger.snapshotChecksum) {
292	    throw new SnapshotError('INVALID_HISTORY', 'history cannot be reconciled to a consistent snapshot');
293	  }
294	  const recoveredWorkspace = new Workspace();
295	  recoveredWorkspace.importJSON(recovered, { mode: 'replace' });
296	  atomicWrite(file, `${JSON.stringify(recovered)}\n`);
297	  return { workspace: recoveredWorkspace, ledger };
298	}
299	
300	function serve(args) {
301	  const { file, port, historyFile } = parseServeArgs(args);
302	  const { workspace, ledger } = loadState(file, historyFile);
303	
304	  const backupFile = historyFile === null ? null : `${historyFile}.bak`;
305	  const server = createDocumentServer({
306	    workspace,
307	    history: ledger,
308	    save: (snapshot, historySnapshot) => {
309	      if (historyFile === null) {
310	        atomicWrite(file, `${JSON.stringify(snapshot)}\n`);
311	      } else {
312	        commitWithHistory(file, historyFile, backupFile, snapshot, historySnapshot);
313	      }
314	    },
315	  });
316	  server.on('error', (error) => {
317	    reportError(new SnapshotError('IO_ERROR', `cannot serve ${file}: ${error.message}`));
318	  });
319	  server.listen(port, '127.0.0.1', () => {
320	    const address = server.address();
321	    process.stdout.write(`${JSON.stringify({ host: address.address, port: address.port })}\n`);
322	  });
323	}
324	
325	function reportError(error) {
326	  const payload = { code: error instanceof SnapshotError ? error.code : 'IO_ERROR' };
327	  if (typeof error.message === 'string') payload.message = error.message;
328	  if (Array.isArray(error.ids)) payload.ids = error.ids;
329	  process.stderr.write(`${JSON.stringify(payload)}\n`);
330	  process.exitCode = 1;
331	}
332	
333	const command = process.argv[2];
334	if (command === 'demo') {
335	  demo();
336	} else if (command === 'migrate') {
337	  try {
338	    migrate(process.argv.slice(3));
339	  } catch (error) {
340	    reportError(error);
341	  }
342	} else if (command === 'export-md') {
343	  try {
344	    exportMd(process.argv.slice(3));
345	  } catch (error) {
346	    reportError(error);
347	  }
348	} else if (command === 'import-md') {
349	  try {
350	    importMd(process.argv.slice(3));
351	  } catch (error) {
352	    reportError(error);
353	  }
354	} else if (command === 'serve') {
355	  try {
356	    serve(process.argv.slice(3));
357	  } catch (error) {
358	    reportError(error);
359	  }
360	} else {
361	  process.stderr.write('Usage: node src/cli.js demo | migrate <base> <incoming> <output> <mode> [--dry-run] | export-md <snapshot> <output-directory> | import-md <base> <input-directory> <output> <mode> [--dry-run] | serve <snapshot> [--port <port>] [--history <file>]\n');
362	  process.exitCode = 1;
363	}
