435	    const { snapshot, result } = commit((candidate, nextLedger) => {
436	      let changed = false;
437	      // Removals run before additions: with uniqueness already verified
438	      // against the final set, a title released by one operation is free for
439	      // a later one whichever order the operations were listed in.
440	      for (const op of operations) {
441	        if (op.type === 'delete') {
442	          candidate.remove(op.id);
443	          if (nextLedger) nextLedger.record(op.id, 'delete', null);
444	          changed = true;
445	        } else if (op.type === 'replace') {
