595	  // Applies the tag rules to the pre-rewrite tag set of every document. Each
596	  // original tag is looked up once, so a rule result is never itself rewritten
597	  // (a→b then b→c moves the original `a` straight to `b`) and swaps resolve
598	  // because `to` names are carried independently of the source keys. Returns
599	  // `{ snapshot, changedIds }` without persisting when `dryRun` is true or the
600	  // rewrite leaves the tag set unchanged.
601	  function commitTagRewrite(rules, dryRun) {
602	    const mapping = new Map(rules.map((rule) => [rule.from, rule.to]));
