675	            // create; a changed live document gets a replace.
676	            const action = current.get(id) ? 'replace' : 'create';
677	            nextLedger.record(id, action, stored);
678	          } else {
679	            nextLedger.record(id, 'delete', null);
680	          }
681	        }
682	      }
683	      return true;
684	    }, { dryRun });
685	    return { snapshot, changedIds: result.changedIds };
