  ]);
  assert.equal(invalid.status, 1);
  assert.equal(invalid.stdout, '');
  assert.equal(JSON.parse(invalid.stderr.trim()).code, 'INVALID_HISTORY');
  assert.equal(fs.readFileSync(corrupt, 'utf8'), '{broken json');
});

